```python
import os

hits = []
for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in {".git", "__pycache__", "node_modules", ".venv", "venv"}]
    for fn in files:
        if "agent" in fn.lower() or "workflow" in fn.lower():
            hits.append(os.path.join(root, fn))

print("candidate files:")
for h in hits:
    print(" ", h)

print("\nmarkdown files present:")
for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in {".git", "__pycache__", "node_modules", ".venv", "venv"}]
    for fn in files:
        if fn.lower().endswith((".md", ".rst", ".txt", ".yaml", ".yml", ".json")):
            print(" ", os.path.join(root, fn))
